package com.carpidi.application;
import com.carpidi.domain.*; import com.carpidi.infrastructure.*; import com.carpidi.support.UnauthorizedException; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RecommendationService { private final UserRepository users; private final ProductRepository products; private final StyleQuestionnaireRepository questionnaires; public RecommendationService(UserRepository users,ProductRepository products,StyleQuestionnaireRepository questionnaires){this.users=users;this.products=products;this.questionnaires=questionnaires;}
 @Transactional public void save(String email,String body,String skin,String height,List<String> styles,boolean consent){User u=users.findByEmailIgnoreCase(email).orElseThrow(UnauthorizedException::new); questionnaires.save(new StyleQuestionnaire(u,body,skin,height,String.join(",",styles),consent));}
 @Transactional(readOnly=true) public List<RecommendationView> recommend(String email){var q=questionnaires.findTopByCustomerEmailIgnoreCaseOrderByCreatedAtDesc(email).orElse(null); String prefs=q==null?"":q.getStylePreferences().toLowerCase(Locale.ROOT); return products.findAll().stream().filter(Product::isActive).map(p->{String text=(p.getName()+" "+Optional.ofNullable(p.getDescription()).orElse("")+" "+p.getCategory().getName()).toLowerCase(Locale.ROOT); long hits=Arrays.stream(prefs.split(",")).filter(s->!s.isBlank()&&text.contains(s.trim())).count(); return new RecommendationView(p.getId(),p.getName(),p.getSlug(),p.getBasePrice(),hits>0?"Coincide con tus preferencias de estilo":"Selección destacada de CARPIDI",hits>0?1.0:0.5);}).sorted(Comparator.comparingDouble(RecommendationView::score).reversed()).limit(6).toList();}
 public record RecommendationView(UUID productId,String name,String slug,java.math.BigDecimal price,String reason,double score) {}
}
